namespace svg;

internal class SvgPathBooleanState
{
    System.Collections.Generic.List<SvgPlanarEdge> firstEdges; System.Collections.Generic.List<SvgPlanarEdge> secondEdges; SvgPathBooleanOperation operation; SvgFillRule firstRule; SvgFillRule secondRule; SvgPathBooleanOptions options; SvgPlanarOptions planar;
    internal SvgPathBooleanState(SvgPlanarFlattenResult firstFlat, SvgPlanarFlattenResult secondFlat, SvgPathBooleanOperation booleanOperation, SvgFillRule firstFillRule, SvgFillRule secondFillRule, SvgPathBooleanOptions booleanOptions, SvgPlanarOptions planarOptions)
    {
        firstEdges = Copy(firstFlat.Edges, 0); secondEdges = Copy(secondFlat.Edges, 1); operation = booleanOperation; firstRule = firstFillRule; secondRule = secondFillRule; options = booleanOptions; planar = planarOptions;
    }

    internal SvgPathBooleanResult Run()
    {
        if (firstEdges.Count > options.MaximumEdges - secondEdges.Count) return new SvgPathBoolean().Failure(SvgPathBooleanError.EdgeLimitExceeded, 0);
        System.Collections.Generic.List<SvgPlanarEdge> combined = new System.Collections.Generic.List<SvgPlanarEdge>(); AddAll(combined, firstEdges); AddAll(combined, secondEdges); SvgPlanarSplitResult arrangement = new SvgPlanarGeometry().SplitEdgesWithEdgesAndOptions(combined, planar); if (!arrangement.Success) return new SvgPathBoolean().Failure(new SvgPathBoolean().MapWithSvgPlanarError(arrangement.Error), arrangement.ComparisonCount);
        System.Collections.Generic.List<SvgPlanarEdge> selected = new System.Collections.Generic.List<SvgPlanarEdge>(); int index = 0; while (index < (arrangement.Edges ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { SvgPathBooleanError error = AddSelectedBoundary(arrangement.Edges[index], selected); if (error != SvgPathBooleanError.None) return new SvgPathBoolean().Failure(error, arrangement.ComparisonCount); index = index + 1; }
        SvgContourReconstructionResult reconstructed = new SvgPlanarGeometry().ReconstructContoursWithEdgesAndOptions(selected, planar); if (!reconstructed.Success) return new SvgPathBoolean().Failure(new SvgPathBoolean().MapWithSvgPlanarError(reconstructed.Error), arrangement.ComparisonCount); SvgGeneratedPathBuilder builder = new SvgGeneratedPathBuilder(); index = 0; while (index < (reconstructed.Contours ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { AddContour(builder, reconstructed.Contours[index]); index = index + 1; }
        return new SvgPathBooleanResult(true, SvgPathBooleanError.None, builder.Build(), reconstructed.Contours.Count, selected.Count, arrangement.ComparisonCount);
    }

    SvgPathBooleanError AddSelectedBoundary(SvgPlanarEdge edge, System.Collections.Generic.List<SvgPlanarEdge> selected)
    {
        double dx = edge.End.X - edge.Start.X; double dy = edge.End.Y - edge.Start.Y; if (!SvgFiniteMath.IsFinite(dx) || !SvgFiniteMath.IsFinite(dy)) return SvgPathBooleanError.NonFiniteResult; double length = SvgPlanarMath.Hypotenuse(dx, dy); if (!SvgFiniteMath.IsFinite(length) || length <= options.Tolerance) return SvgPathBooleanError.None;
        SvgFiniteResult middleX = SvgFiniteMath.Lerp(edge.Start.X, edge.End.X, 0.5); SvgFiniteResult middleY = SvgFiniteMath.Lerp(edge.Start.Y, edge.End.Y, 0.5); if (!middleX.Success || !middleY.Success) return SvgPathBooleanError.NonFiniteResult; double offset = Lower(length / 4, options.Tolerance * 4); if (!SvgFiniteMath.IsFinite(offset) || offset <= 0) return SvgPathBooleanError.NonFiniteResult; double normalX = -dy / length; double normalY = dx / length; SvgPoint? left = Offset(middleX.Value, middleY.Value, normalX, normalY, offset); SvgPoint? right = Offset(middleX.Value, middleY.Value, -normalX, -normalY, offset); if (left == null || right == null) return SvgPathBooleanError.NonFiniteResult;
        SvgPlanarOptions sampleOptions = new SvgPathBoolean().Planar(options); sampleOptions.Tolerance = offset / 8; SvgPlanarWindingResult firstLeft = new SvgPlanarGeometry().ClassifyWindingWithEdgesAndPointAndFillRuleAndOptions(firstEdges, left, firstRule, sampleOptions); SvgPlanarWindingResult secondLeft = new SvgPlanarGeometry().ClassifyWindingWithEdgesAndPointAndFillRuleAndOptions(secondEdges, left, secondRule, sampleOptions); SvgPlanarWindingResult firstRight = new SvgPlanarGeometry().ClassifyWindingWithEdgesAndPointAndFillRuleAndOptions(firstEdges, right, firstRule, sampleOptions); SvgPlanarWindingResult secondRight = new SvgPlanarGeometry().ClassifyWindingWithEdgesAndPointAndFillRuleAndOptions(secondEdges, right, secondRule, sampleOptions); if (!firstLeft.Success || !secondLeft.Success || !firstRight.Success || !secondRight.Success) return SvgPathBooleanError.InvalidArgument;
        bool leftFilled = Result(firstLeft.Contains, secondLeft.Contains); bool rightFilled = Result(firstRight.Contains, secondRight.Contains); if (leftFilled == rightFilled) return SvgPathBooleanError.None; SvgPlanarEdge boundary = leftFilled ? SvgPlanarEdge.Create(edge.Start, edge.End, edge.SourceIndex, edge.StartAmount, edge.EndAmount) : SvgPlanarEdge.Create(edge.End, edge.Start, edge.SourceIndex, edge.EndAmount, edge.StartAmount); AddUnique(selected, boundary); return SvgPathBooleanError.None;
    }

    bool Result(bool firstContains, bool secondContains) { if (operation == SvgPathBooleanOperation.Union) return firstContains || secondContains; if (operation == SvgPathBooleanOperation.Intersection) return firstContains && secondContains; if (operation == SvgPathBooleanOperation.Difference) return firstContains && !secondContains; return firstContains != secondContains; }
    void AddUnique(System.Collections.Generic.List<SvgPlanarEdge> selected, SvgPlanarEdge edge) { int index = 0; while (index < selected.Count) { SvgPlanarEdge existing = selected[index]; if (SvgPlanarMath.Distance(existing.Start, edge.Start) <= options.Tolerance && SvgPlanarMath.Distance(existing.End, edge.End) <= options.Tolerance) return; if (SvgPlanarMath.Distance(existing.Start, edge.End) <= options.Tolerance && SvgPlanarMath.Distance(existing.End, edge.Start) <= options.Tolerance) { selected.RemoveAt(index); return; } index = index + 1; } selected.Add(edge); }

    static System.Collections.Generic.List<SvgPlanarEdge> Copy(System.Collections.Generic.List<SvgPlanarInputEdge>? input, int operand) { System.Collections.Generic.List<SvgPlanarEdge> result = new System.Collections.Generic.List<SvgPlanarEdge>(); int index = 0; while (index < (input ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { SvgPlanarEdge edge = input[index].Edge; result.Add(SvgPlanarEdge.Create(edge.Start, edge.End, operand, edge.StartAmount, edge.EndAmount)); index = index + 1; } return result; }
    static void AddAll(System.Collections.Generic.List<SvgPlanarEdge> target, System.Collections.Generic.List<SvgPlanarEdge> source) { int index = 0; while (index < source.Count) { target.Add(source[index]); index = index + 1; } }
    static SvgPoint? Offset(double x, double y, double nx, double ny, double amount) { SvgFiniteResult offsetX = SvgFiniteMath.Multiply(nx, amount); SvgFiniteResult offsetY = SvgFiniteMath.Multiply(ny, amount); if (!offsetX.Success || !offsetY.Success) return null; SvgFiniteResult resultX = SvgFiniteMath.Add(x, offsetX.Value); SvgFiniteResult resultY = SvgFiniteMath.Add(y, offsetY.Value); return resultX.Success && resultY.Success ? new SvgPoint(resultX.Value, resultY.Value) : null; }
    static void AddContour(SvgGeneratedPathBuilder builder, SvgPlanarContour contour) { if (contour.Points.Count < 4) return; builder.MoveTo(contour.Points[0].X, contour.Points[0].Y); int index = 1; while (index + 1 < contour.Points.Count) { builder.LineTo(contour.Points[index].X, contour.Points[index].Y); index = index + 1; } builder.Close(); }
    static double Lower(double first, double second) { return first < second ? first : second; }
}
